                    out += ',';
                    ddon_dump_field(out, "mGlobal", p, p->mGlobal);
                    out += ',';
                    ddon_dump_field(out, "mID1", p, p->mID1);
                    out += ',';
                    ddon_dump_field(out, "mID2", p, p->mID2);
                    out += ',';
                    ddon_dump_field(out, "mID3", p, p->mID3);
                    out += ',';
                    ddon_dump_field(out, "mLimit", p, p->mLimit);
                    out += ',';
                    ddon_dump_field(out, "mCenterVol", p, p->mCenterVol);
                    out += ',';
                    ddon_dump_field(out, "mVolCurveId", p, p->mVolCurveId);
                    out += ',';
                    ddon_dump_field(out, "mEffectCurveId", p, p->mEffectCurveId);
                    out += ',';
                    ddon_dump_field(out, "mLfeCurveId", p, p->mLfeCurveId);
